local ChrismatoryMaker = {}
local PRODUCTS = {
    pewter_chrismatory = { name = "Pustrasta krizmatija", tinCost = 1, time = 2, cost = 25, sanctity = 3, description = "Pustrasta krizmatija za sveta olja." },
    silver_chrismatory = { name = "Srebrna krizmatija", silverCost = 2, time = 3, cost = 90, sanctity = 7, prestige = 2, description = "Srebrna krizmatija z graviranjem." },
    crystal_chrismatory = { name = "Kristalna krizmatija", glassCost = 2, silverCost = 1, time = 5, cost = 220, sanctity = 11, prestige = 5, happiness = 1, description = "Kristalna krizmatija v srebrnem okvirju." },
    gold_chrismatory = { name = "Zlata krizmatija", goldCost = 1, silverCost = 1, glassCost = 1, time = 7, cost = 480, sanctity = 15, prestige = 11, happiness = 2, description = "Zlata krizmatija za škofijske slovesnosti." },
    jewel_chrismatory = { name = "Draguljna krizmatija", goldCost = 2, silverCost = 1, jewelCost = 1, glassCost = 1, time = 10, cost = 1000, sanctity = 20, prestige = 22, happiness = 4, description = "Krizmatija z dragulji za nadškofa." },
    royal_triple_chrismatory = { name = "Kraljevski trojna krizmatija", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, glassCost = 2, time = 14, cost = 2400, sanctity = 32, prestige = 55, happiness = 11, description = "Veliki trojni kraljevski krizmatič za olja krstma, birme in bolniškega maziljenja." },
}
local BUILDINGS = {
    workshop = { name = "Krizmatijska delavnica", cost = { gold = 290, wood = 120 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Krizmatijska kovačija", cost = { gold = 850, wood = 220, stone = 200, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    crystal_room = { name = "Kristalna soba", cost = { gold = 1800, wood = 300, stone = 400, glass = 8, silver = 25 }, upkeep = 42, qualityBonus = 30 },
    royal_chrismatory_atelier = { name = "Kraljevski atelje krizmatij", cost = { gold = 7000, wood = 600, stone = 800, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 33 },
}
ChrismatoryMaker.tinStock = 12; ChrismatoryMaker.silverStock = 8; ChrismatoryMaker.goldStock = 6; ChrismatoryMaker.glassStock = 8; ChrismatoryMaker.jewelStock = 6; ChrismatoryMaker.pearlStock = 4
ChrismatoryMaker.productStock = {}; ChrismatoryMaker.buildings = {}; ChrismatoryMaker.maker = nil; ChrismatoryMaker.activeMaking = {}; ChrismatoryMaker.totalProducts = 0; ChrismatoryMaker.dayTimer = 0
function ChrismatoryMaker.init() ChrismatoryMaker.tinStock=12; ChrismatoryMaker.silverStock=8; ChrismatoryMaker.goldStock=6; ChrismatoryMaker.glassStock=8; ChrismatoryMaker.jewelStock=6; ChrismatoryMaker.pearlStock=4; ChrismatoryMaker.productStock={}; ChrismatoryMaker.buildings={}; ChrismatoryMaker.maker=nil; ChrismatoryMaker.activeMaking={}; ChrismatoryMaker.totalProducts=0; ChrismatoryMaker.dayTimer=0; print("[ChrismatoryMaker] Royal Chrismatory Maker System initialized (6 products, 4 buildings)") end
function ChrismatoryMaker.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChrismatoryMaker.maker={name=n or ("Krizmatijar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krizmatijar najet: %s (spretnost: %d)",ChrismatoryMaker.maker.name,s),"success") end; return true end
function ChrismatoryMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChrismatoryMaker.build(id) local ok,e=ChrismatoryMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChrismatoryMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChrismatoryMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChrismatoryMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChrismatoryMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and ChrismatoryMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.silverCost and ChrismatoryMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChrismatoryMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and ChrismatoryMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.jewelCost and ChrismatoryMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChrismatoryMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChrismatoryMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ChrismatoryMaker.maker then return false,"Potreben krizmatijar" end; return true end
function ChrismatoryMaker.make(pt,qty) qty=qty or 1; local ok,e=ChrismatoryMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then ChrismatoryMaker.tinStock=ChrismatoryMaker.tinStock-d.tinCost*qty end; if d.silverCost then ChrismatoryMaker.silverStock=ChrismatoryMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChrismatoryMaker.goldStock=ChrismatoryMaker.goldStock-d.goldCost*qty end; if d.glassCost then ChrismatoryMaker.glassStock=ChrismatoryMaker.glassStock-d.glassCost*qty end; if d.jewelCost then ChrismatoryMaker.jewelStock=ChrismatoryMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChrismatoryMaker.pearlStock=ChrismatoryMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ChrismatoryMaker.maker then t=math.max(1,t-math.floor(ChrismatoryMaker.maker.skill/12)) end; table.insert(ChrismatoryMaker.activeMaking,{id="chrismatory_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChrismatoryMaker.completeMaking(m) local q=1.0+(ChrismatoryMaker.getQualityBonus()/100); if ChrismatoryMaker.maker then q=q+(ChrismatoryMaker.maker.skill/180) end; q=math.min(2.0,q); ChrismatoryMaker.productStock[m.productType]=(ChrismatoryMaker.productStock[m.productType] or 0)+m.quantity; ChrismatoryMaker.totalProducts=ChrismatoryMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChrismatoryMaker.maker then ChrismatoryMaker.maker.itemsMade=ChrismatoryMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ChrismatoryMaker.maker.skill=math.min(100,ChrismatoryMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krizmatija izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chrismatory.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function ChrismatoryMaker.update(dt) if not _G.state then return end; ChrismatoryMaker.dayTimer=ChrismatoryMaker.dayTimer+dt; if ChrismatoryMaker.dayTimer>=30 then ChrismatoryMaker.dayTimer=0; for i=#ChrismatoryMaker.activeMaking,1,-1 do local m=ChrismatoryMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChrismatoryMaker.completeMaking(m); table.remove(ChrismatoryMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChrismatoryMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChrismatoryMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChrismatoryMaker.getStats() return {tinStock=ChrismatoryMaker.tinStock,silverStock=ChrismatoryMaker.silverStock,goldStock=ChrismatoryMaker.goldStock,glassStock=ChrismatoryMaker.glassStock,jewelStock=ChrismatoryMaker.jewelStock,pearlStock=ChrismatoryMaker.pearlStock,productStock=ChrismatoryMaker.productStock,numBuildings=#ChrismatoryMaker.buildings,hasMaker=ChrismatoryMaker.maker~=nil,makerName=ChrismatoryMaker.maker and ChrismatoryMaker.maker.name or "—",makerSkill=ChrismatoryMaker.maker and ChrismatoryMaker.maker.skill or 0,activeMaking=#ChrismatoryMaker.activeMaking,totalProducts=ChrismatoryMaker.totalProducts} end
return ChrismatoryMaker
